size:10px}.option.locked{opacity:.7}.option-visual{height:22px;display:flex;align-items:center;margin-bottom:8px}.paint-chip{width:28px;height:19px;border-radius:2px;box-shadow:inset 0 1px 5px #ffffff42,0 3px 7px #0008;transform:skew(-18deg)}.wheel-visual{width:22px;height:22px;border:3px solid #8a8b8f;border-radius:50%;position:relative}.wheel-visual:before{content:"";position:absolute;inset:4px;border:1px solid #bbb;border-radius:50%}.wheel-visual:after{content:"";position:absolute;left:8px;top:1px;height:15px;width:1px;background:#888;transform:rotate(45deg);box-shadow:0 0 0 0 #888}.body-visual{font-size:20px;color:var(--acid);line-height:1}.style-visual{font-size:18px;color:#d4a0ff}.option-name{display:block;font:700 12px/1 var(--font-display);letter-spacing:.3px;white-space:nowrap;text-overflow:ellipsis;overflow:hidden}.option-meta{display:block;font-size:8px;color:#86878d;margin-top:6px;letter-spacing:.3px}.option-meta b{color:var(--acid);font-weight:600}.option-price{position:absolute;right:8px;bottom:8px;font-size:8px;color:#b7b7ba}.option-price.free{color:#a7be56}.build-stats{border-top:1px solid #303137;margin-top:20px;padding-top:13px}.stats-title{display:flex;justify-content:space-between;font-size:8px;letter-spacing:1.3px;font-weight:700;color:#c1c1c3;margin-bottom:13px}.spec-level{color:#828388;font-weight:500}.spec-level b{color:var(--acid);font-weight:700}.stat-row{display:grid;grid-template-columns:77px 1fr 30px;align-items:center;gap:9px;margin:9px 0;font-size:7px;letter-spacing:.9px;color:#85868b}.stat-row b{font:700 11px var(--font-display);color:#c6c6c8;text-align:right}.stat-track{height:3px;background:#34353a;overflow:hidden}.stat-track i{height:100%;display:block;background:var(--acid);box-shadow:0 0 8px #d5f26370;transition:width .3s}.style-track i{background:#ff744e}.grip-track i{background:#8c91ff}.save-build{flex:none;background:var(--acid);color:#171a10;border:0;min-height:48px;margin-top:16px;font:800 13px var(--font-display);letter-spacing:1px;text-align:left;padding:0 16px;position:relative;box-shadow:0 5px 20px #d5f26312;transition:.15s}.save-build:hover{background:#e2ff75;transform:translateY(-1px)}.save-build>span{margin-right:8px}.save-build i{font-style:normal;position:absolute;right:17px;font-size:18px;top:12px}.bottom-bar{height:43px;border-top:1px solid #ffffff0c;display:flex;align-items:center;padding:0 4.2%;color:#85858a;font-size:8px;letter-spacing:1px}.footer-location{display:flex;align-items:center;gap:9px}.location-icon{color:var(--acid);font-size:14px}.footer-location i{color:#515257;font-style:normal}.footer-location small{font-size:8px;color:#626369}.footer-center{margin:auto;display:flex;align-items:center;gap:7px}.keycap{font:700 8px var(--font-body);color:#aaa;border:1px solid #45464a;padding:3px 5px}.footer-center small{font-size:7px}.footer-divider{color:#48494c;margin:0 7px}.footer-right{font-size:7px;color:#696a6f}.footer-right span{color:var(--acid);font-size:10px;margin-left:7px}.toast{position:fixed;z-index:20;bottom:60px;left:50%;transform:translate(-50%,20px);padding:11px 18px;background:var(--acid);color:#171a10;font-size:11px;font-weight:700;letter-spacing:.4px;box-shadow:0 8px 25px #0008;opacity:0;pointer-events:none;transition:.25s}.toast.show{opacity:1;transform:translate(-50%,0)}.modal-backdrop{position:fixed;inset:0;z-index:15;background:#090a0bd9;display:grid;place-items:center;padding:20px;opacity:0;visibility:hidden;transition:.25s;backdrop-filter:blur(8px)}.modal-backdrop.open{opacity:1;visibility:visible}.save-modal{position:relative;width:min(400px,100%);background:linear-gradient(145deg,#222329,#16171a);border:1px solid #44464b;padding:34px;text-align:center;box-shadow:0 20px 70px #0009}.modal-close{position:absolute;right:12px;top:8px;background:none;border:0;font-size:24px;color:#aaa}.modal-badge{width:42px;height:42px;border:1px solid #626b3a;color:var(--acid);display:grid;place-items:center;margin:0 auto 15px;border-radius:50%;font-size:19px}.save-modal h2{font:800 31px var(--font-display);margin:7px 0}.save-modal p{font-size:12px;color:#aaa;line-height:1.6;max-width:290px;margin:10px auto 18px}.saved-car{border-block:1px solid #34353a;padding:13px;font:700 17px var(--font-display);letter-spacing:1px;color:var(--acid);margin-bottom:18px}.modal-done{height:42px;width:100%;border:0;background:var(--acid);color:#171a10;font:800 12px var(--font-display);letter-spacing:1px}.modal-done span{float:right;font-size:18px;margin-top:-3px}
