import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';

const cars=[
 {name:'LA FIERA 84',class:'CLASSIC COMPACT',type:'HATCHBACK',paint:'#df503c',shape:'hatch',cost:0},
 {name:'TORO CALLEJERO',class:'STREET PICKUP',type:'PICKUP',paint:'#a9b5a2',shape:'truck',cost:650},
 {name:'NOVA BRASÍLIA',class:'COUPÉ SPORT',type:'SPORT COUPÉ',paint:'#4a72b8',shape:'coupe',cost:1200}
];
const paints=[['CANDY APPLE','#df503c',0],['MANGO POP','#ef9f32',180],['PACIFIC BLUE','#287c9d',180],['LIMA NEÓN','#a9c746',220],['NOCHE BLACK','#25272b',260],['PERLA ROSA','#d47e91',300]];
const wheelSets=[['STOCK STEEL','stock',0],['CINCO SPOKE','five',280],['MESH CLASSIC','mesh',380],['GOLD RUSH','gold',440],['CHROME DEEP','chrome',520]];
const bodySets=[['CLEAN CUT','clean',0],['STREET KIT','street',420],['WIDE BODY','wide',680],['RALLY SPEC','rally',560]];
const styleSets=[['NO EXTRAS','none',0],['UNDERGLOW','glow',320],['CALLE STRIPES','stripes',260],['COLOMBIA PRIDE','flag',240]];
const categories={paint:{eyebrow:'COLOR & FINISH',title:'PAINT SHOP',list:paints},wheels:{eyebrow:'ROLL IN STYLE',title:'WHEEL SHOP',list:wheelSets},body:{eyebrow:'FORM & FUNCTION',title:'BODY WORK',list:bodySets},style:{eyebrow:'MAKE A STATEMENT',title:'PERSONAL TOUCH',list:styleSets}};
const state={credits:2450,car:0,category:'paint',selection:cars.map(c=>({paint:c.paint,wheels:'stock',body:'clean',style:'none'})),unlocked:new Set(['paint:CANDY APPLE','wheels:STOCK STEEL','body:CLEAN CUT','style:NO EXTRAS']),rotating:false};
const $=s=>document.querySelector(s), canvasHost=$('#carCanvas');
let scene,camera,renderer,carGroup,carMaterials={}, wheelParts=[], underglow, animationId, drag=null, autoRotate=false, yaw=.45, pitch=.12, cameraDistance=7.8;

function init3D(){
 scene=new THREE.Scene();scene.background=new THREE.Color('#202126');scene.fog=new THREE.Fog('#202126',13,27);
 camera=new THREE.PerspectiveCamera(34,1,.1,80);camera.position.set(6.5,3.4,7.6);camera.lookAt(0,.67,0);
 renderer=new THREE.WebGLRenderer({antialias:true,alpha:false,preserveDrawingBuffer:true});renderer.setPixelRatio(Math.min(window.devicePixelRatio||1,2));renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;canvasHost.appendChild(renderer.domElement);
 scene.add(new THREE.HemisphereLight(0xc9d2e3,0x35312d,2.0));const key=new THREE.DirectionalLight(0xffedcd,3.2);key.position.set(-3,7,5);key.castShadow=true;key.shadow.mapSize.set(1024,1024);key.shadow.camera.left=-7;key.shadow.camera.right=7;key.shadow.camera.top=7;key.shadow.camera.bottom=-7;scene.add(key);
 const rim=new THREE.DirectionalLight(0xb7d2ff,2.4);rim.position.set(3,4,-5);scene.add(rim);const fill=new THREE.PointLight(0xd5f263,1.3,9);fill.position.set(-3,2,2);scene.add(fill);
 const floor=new THREE.Mesh(new THREE.PlaneGeometry(200,200),new THREE.MeshStandardMaterial({color:'#24252a',roughness:.78,metalness:.1}));floor.rotation.x=-Math.PI/2;floor.position.y=-.02;floor.receiveShadow=true;scene.add(floor);
 const grid=new THREE.GridHelper(80,80,'#3b3d42','#303136');grid.position.y=-.008;grid.material.transparent=true;grid.material.opacity=.32;scene.add(grid);
 // Soft studio panels
 for(const [x,z,w,h,color] of [[-5,-3,2,4,'#32343a'],[5,-4,2,4,'#292b30']]){const panel=new THREE.Mesh(new THREE.PlaneGeometry(w,h),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.22,side:THREE.DoubleSide}));panel.position.set(x,2,z);panel.lookAt(0,2,0);scene.add(panel)}
 buildCar();resize();window.addEventListener('resize',resize);renderer.domElement.addEventListener('pointerdown',onDown);window.addEventListener('pointermove',onMove);window.addEventListener('pointerup',onUp);renderer.domElement.addEventListener('wheel',e=>{cameraDistance=THREE.MathUtils.clamp(cameraDistance+e.deltaY*.004,5.5,10);e.preventDefault()},{passive:false});
 animate();
}
function mat(color,roughness=.45,metalness=.1,extra={}){return new THREE.MeshStandardMaterial({color,roughness,metalness,...extra})}
function mesh(geo,material,parent=carGroup,x=0,y=0,z=0){const m=new THREE.Mesh(geo,material);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function box(parent,x,y,z,sx,sy,sz,material){return mesh(new THREE.BoxGeometry(sx,sy,sz),material,parent,x,y,z)}
function extrudedShape(points,depth,material,parent,x=0,y=0,z=0){const shape=new THREE.Shape();shape.moveTo(points[0][0],points[0][1]);for(let i=1;i<points.length;i++)shape.lineTo(points[i][0],points[i][1]);shape.closePath();const g=new THREE.ExtrudeGeometry(shape,{depth,bevelEnabled:true,bevelSegments:2,steps:1,bevelSize:.035,bevelThickness:.025});g.translate(0,0,-depth/2);return mesh(g,material,parent,x,y,z)}
function buildCar(){
 if(carGroup)scene.remove(carGroup);carGroup=new THREE.Group();scene.add(carGroup);const model=cars[state.car],config=state.selection[state.car];carMaterials={};wheelParts=[];
 const paint=mat(config.paint,.28,.28,{clearcoat:.65,clearcoatRoughness:.2});carMaterials.paint=paint;const dark=mat('#202126',.48,.24),glass=mat('#17232a',.19,.55,{transparent:true,opacity:.86}),trim=mat('#393a3c',.4,.62),rubber=mat('#161719',.82,.03),chrome=mat('#aeb5b6',.22,.84),lamp=mat('#fff0c8',.22,.25,{emissive:'#ffe4a0',emissiveIntensity:1.2}),red=mat('#e44332',.24,.2,{emissive:'#7d1109',emissiveIntensity:.3});
