let toastTimer;function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2100)}
const race={open:false,running:false,lane:1,distance:0,speed:0,best:Number(localStorage.getItem('latinGarageBest')||0),hits:0,lastHit:0,spawnTimer:0,lastTime:0,obstacles:[],raf:0};
const raceLanes=[22,50,78];
function openRace(){race.open=true;race.running=false;cancelAnimationFrame(race.raf);$('#raceOverlay').classList.add('open');$('#raceOverlay').classList.remove('running');$('#raceTitle').innerHTML='STREET <em>RUN</em>';$('#raceStart').innerHTML='START ENGINE <span>→</span>';$('#raceResult').textContent='';$('#distanceHud').textContent='0m';$('#speedHud').innerHTML='0 <i>KM/H</i>';$('#bestHud').textContent=race.best?`${race.best}m`:'—';$('#raceStart').focus()}
function closeRace(){race.running=false;race.open=false;cancelAnimationFrame(race.raf);$('#raceOverlay').classList.remove('open','running');clearTraffic()}
function clearTraffic(){race.obstacles.forEach(o=>o.el.remove());race.obstacles=[]}
function startRace(){clearTraffic();race.running=true;race.lane=1;race.distance=0;race.speed=0;race.hits=0;race.spawnTimer=.9;race.lastHit=0;race.lastTime=performance.now();$('#raceResult').textContent='DODGE TRAFFIC · REACH 800M';$('#raceTitle').innerHTML='STREET <em>RUN</em>';$('#raceStart').innerHTML='ABANDON RUN <span>×</span>';$('#raceOverlay').classList.add('running');setPlayerLane();race.raf=requestAnimationFrame(updateRace)}
function setPlayerLane(){const car=$('.race-car');car.style.top=`${raceLanes[race.lane]}%`;car.style.bottom='auto';car.style.transform='translateY(-50%) scaleX(1.7)'}
function steer(dir){if(!race.running)return;race.lane=THREE.MathUtils.clamp(race.lane+dir,0,2);setPlayerLane()}
function spawnTraffic(){const el=document.createElement('span');el.className='traffic-car';el.textContent='▰';const lane=Math.floor(Math.random()*3);el.style.top=`${raceLanes[lane]}%`;$('.race-road').appendChild(el);race.obstacles.push({el,lane,x:105})}
function updateRace(now){if(!race.running)return;const dt=Math.min(.05,(now-race.lastTime)/1000);race.lastTime=now;race.speed=Math.min(142,race.speed+dt*34);if(now<race.lastHit)race.speed=Math.max(58,race.speed-dt*42);race.distance+=race.speed/3.6*dt;race.spawnTimer-=dt;if(race.spawnTimer<=0){spawnTraffic();race.spawnTimer=1.35+Math.random()*.55}
 const carX=16;for(let i=race.obstacles.length-1;i>=0;i--){const o=race.obstacles[i];o.x-=race.speed/3.6*dt/8.5;o.el.style.left=`${o.x}%`;if(o.lane===race.lane&&o.x<=carX+7&&o.x>=carX-2&&now>race.lastHit){race.hits++;race.lastHit=now+1200;o.el.remove();race.obstacles.splice(i,1);$('#raceResult').textContent=race.hits>=3?'TOO MANY HITS — RUN ENDED':`CRASH! ${3-race.hits} ${3-race.hits===1?'HIT':'HITS'} LEFT`;if(race.hits>=3){finishRace(false);return}continue}if(o.x< -15){o.el.remove();race.obstacles.splice(i,1)}}
 $('#distanceHud').textContent=`${Math.floor(race.distance)}m`;$('#speedHud').innerHTML=`${Math.round(race.speed)} <i>KM/H</i>`;if(race.distance>=800){finishRace(true);return}race.raf=requestAnimationFrame(updateRace)}
function finishRace(completed){race.running=false;cancelAnimationFrame(race.raf);$('#raceOverlay').classList.remove('running');const distance=Math.floor(race.distance);if(distance>race.best){race.best=distance;try{localStorage.setItem('latinGarageBest',String(distance))}catch{}}const reward=Math.max(25,Math.round(distance*.28)+(completed?100:0)-race.hits*25);state.credits+=reward;updateLabels();$('#bestHud').textContent=`${race.best}m`;$('#raceTitle').innerHTML=completed?'RUN <em>COMPLETE</em>':'RUN <em>OVER</em>';$('#raceResult').textContent=`${completed?'FINISH LINE!':'WRECKED'} · +${reward} CRÉDITOS · ${race.hits} HITS`;$('#raceStart').innerHTML='RUN AGAIN <span>→</span>';clearTraffic()}
function setupRace(){const overlay=$('#raceOverlay'),start=$('#raceStart');$('#runButton').addEventListener('click',openRace);$('#closeRace').addEventListener('click',closeRace);overlay.addEventListener('click',e=>{if(e.target===overlay)closeRace()});start.addEventListener('click',()=>race.running?closeRace():startRace());[['leftControl',-1],['rightControl',1]].forEach(([id,dir])=>{const b=$(`#${id}`);b.addEventListener('pointerdown',e=>{e.preventDefault();steer(dir)});b.addEventListener('click',()=>steer(dir))});window.addEventListener('keydown',e=>{if(!race.open)return;if(['ArrowLeft','ArrowRight','a','A','d','D',' '].includes(e.key))e.preventDefault();if(e.key==='ArrowLeft'||e.key==='a'||e.key==='A')steer(-1);if(e.key==='ArrowRight'||e.key==='d'||e.key==='D')steer(1);if(e.key==='Escape')closeRace()});$('.race-road').addEventListener('pointerdown',e=>{if(!race.running)return;const rect=e.currentTarget.getBoundingClientRect();steer(e.clientX<rect.left+rect.width/2?-1:1)});}
