 function setPlayerLane(){const car=$('.race-car');car.style.top=`${raceLanes[race.lane]}%`;car.style.bottom='auto';car.style.transform='translateY(-50%) scaleX(1.7)'}
 function steer(dir){if(!race.running)return;race.lane=THREE.MathUtils.clamp(race.lane+dir,0,2);setPlayerLane()}
 function spawnTraffic(){const el=document.createElement('span');el.className='traffic-car';el.textContent='▰';const lane=Math.floor(Math.random()*3);el.style.top=`${raceLanes[lane]}%`;$('.race-road').appendChild(el);race.obstacles.push({el,lane,x:105})}
 function updateRace(now){if(!race.running)return;const dt=Math.min(.05,(now-race.lastTime)/1000);race.lastTime=now;race.speed=Math.min(142,race.speed+dt*34);if(now<race.lastHit)race.speed=Math.max(58,race.speed-dt*42);race.distance+=race.speed/3.6*dt;race.spawnTimer-=dt;if(race.spawnTimer<=0){spawnTraffic();race.spawnTimer=1.35+Math.random()*.55}
- const carX=16;for(let i=race.obstacles.length-1;i>=0;i--){const o=race.obstacles[i];o.x-=race.speed/3.6*dt/60;o.el.style.left=`${o.x}%`;if(o.lane===race.lane&&o.x<=carX+7&&o.x>=carX-2&&now>race.lastHit){race.hits++;race.lastHit=now+1200;o.el.remove();race.obstacles.splice(i,1);$('#raceResult').textContent=race.hits>=3?'TOO MANY HITS — RUN ENDED':`CRASH! ${3-race.hits} ${3-race.hits===1?'HIT':'HITS'} LEFT`;if(race.hits>=3){finishRace(false);return}continue}if(o.x< -15){o.el.remove();race.obstacles.splice(i,1)}}
+ const carX=16;for(let i=race.obstacles.length-1;i>=0;i--){const o=race.obstacles[i];o.x-=race.speed/3.6*dt/9;o.el.style.left=`${o.x}%`;if(o.lane===race.lane&&o.x<=carX+7&&o.x>=carX-2&&now>race.lastHit){race.hits++;race.lastHit=now+1200;o.el.remove();race.obstacles.splice(i,1);$('#raceResult').textContent=race.hits>=3?'TOO MANY HITS — RUN ENDED':`CRASH! ${3-race.hits} ${3-race.hits===1?'HIT':'HITS'} LEFT`;if(race.hits>=3){finishRace(false);return}continue}if(o.x< -15){o.el.remove();race.obstacles.splice(i,1)}}
