 function finishRace(completed){race.running=false;cancelAnimationFrame(race.raf);$('#raceOverlay').classList.remove('running');const distance=Math.floor(race.distance);if(distance>race.best){race.best=distance;try{localStorage.setItem('latinGarageBest',String(distance))}catch{}}const reward=Math.max(25,Math.round(distance*.28)+(completed?100:0)-race.hits*25);state.credits+=reward;updateLabels();$('#bestHud').textContent=`${race.best}m`;$('#raceTitle').innerHTML=completed?'RUN <em>COMPLETE</em>':'RUN <em>OVER</em>';$('#raceResult').textContent=`${completed?'FINISH LINE!':'WRECKED'} · +${reward} CRÉDITOS · ${race.hits} HITS`;$('#raceStart').innerHTML='RUN AGAIN <span>→</span>';clearTraffic()}
 function setupRace(){const overlay=$('#raceOverlay'),start=$('#raceStart');$('#runButton').addEventListener('click',openRace);$('#closeRace').addEventListener('click',closeRace);overlay.addEventListener('click',e=>{if(e.target===overlay)closeRace()});start.addEventListener('click',()=>race.running?closeRace():startRace());[['leftControl',-1],['rightControl',1]].forEach(([id,dir])=>$(`#${id}`).addEventListener('click',()=>steer(dir)));window.addEventListener('keydown',e=>{if(!race.open)return;if(['ArrowLeft','ArrowRight','a','A','d','D',' '].includes(e.key))e.preventDefault();if(e.key==='ArrowLeft'||e.key==='a'||e.key==='A')steer(-1);if(e.key==='ArrowRight'||e.key==='d'||e.key==='D')steer(1);if(e.key==='Escape')closeRace()});$('.race-road').addEventListener('pointerdown',e=>{if(!race.running)return;const rect=e.currentTarget.getBoundingClientRect();steer(e.clientX<rect.left+rect.width/2?-1:1)});}
 function setupUI(){setupCars();renderOptions();updateLabels();document.querySelectorAll('.category').forEach(b=>b.addEventListener('click',()=>{document.querySelector('.category.active').classList.remove('active');b.classList.add('active');state.category=b.dataset.category;renderOptions()}));$('#resetButton').addEventListener('click',()=>{state.selection[state.car]={paint:cars[state.car].paint,wheels:'stock',body:'clean',style:'none'};buildCar();renderOptions();toast('Build reset to factory spec')});$('#rotateButton').addEventListener('click',e=>{autoRotate=!autoRotate;e.currentTarget.classList.toggle('active',autoRotate);toast(autoRotate?'Auto rotate on':'Auto rotate off')});$('#photoButton').addEventListener('click',()=>{try{const a=document.createElement('a');a.download=`latin-garage-${cars[state.car].name.toLowerCase().replaceAll(' ','-')}.png`;a.href=renderer.domElement.toDataURL('image/png');a.click();toast('Studio shot downloaded')}catch{toast('Could not capture preview')}});$('#saveButton').addEventListener('click',()=>{const cfg=state.selection[state.car];$('#savedCar').textContent=`${cars[state.car].name}  ·  ${cfg.body.toUpperCase()}  ·  ${cfg.wheels.toUpperCase()}`;$('#modal').classList.add('open')});const close=()=>$('#modal').classList.remove('open');$('#closeModal').addEventListener('click',close);$('#doneButton').addEventListener('click',close);$('#modal').addEventListener('click',e=>{if(e.target.id==='modal')close()});$('#menuButton').addEventListener('click',()=>toast('Your garage is open — build something legendary'));document.querySelector('.plus').addEventListener('click',()=>toast('Earn créditos by completing street runs!'));window.addEventListener('keydown',e=>{if(race.open)return;if(e.key==='ArrowRight')selectCar((state.car+1)%cars.length);if(e.key==='ArrowLeft')selectCar((state.car+cars.length-1)%cars.length);if(e.key==='Escape')$('#modal').classList.remove('open')})}

